fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // If the array is empty, it vacuously has only one distinct element.
    if let Some(&first) = arr.first() {
        // Check that every element equals the first one.
        arr.iter().all(|&x| x == first)
    } else {
        true
    }
}

